template<typename T>
class _zmalloc
{
public:
	/* __ct__15_zmalloc<4four>FUi (0x141830) / __ct__17_zmalloc<6twelve>FUi (0x1418f0); the ELF has no destructor */
	_zmalloc(size_t count)
	{
		m_bytes = sizeof(T);
		m_size = count;
		m_count = 0;
		m_peak = 0;
		m_overflow = 0;
		init_page();
	}

	/* init_page (0x141870 four / 0x141930 twelve): one page of m_size records, chained into the free list. */
	void init_page()
	{
		T* p = (T*)_calloc(sizeof(T), m_size, "main.cpp", 0x4c);
		m_page = p;
		m_head = p;

		for (u32 i = 0; i < m_size - 1; i++)
		{
			p->next = p + 1;
			p++;
		}

		p->next = NULL;
		m_tail = p + 1;
	}

	/* acquire (0x141710 four / 0x1417a0 twelve; inlined into operator new): pop a record of exactly
	 * m_bytes; when the page is exhausted, count the overflow and fall back to the heap. */
	T* acquire(size_t size)
	{
		if (size != m_bytes)
			return NULL;

		if (m_head == NULL)
		{
			m_overflow++;
			return (T*)_malloc(sizeof(T), "main.cpp", 0x5f);
		}

		m_count++;

		if (m_peak < m_count)
			m_peak = m_count;

		T* p = m_head;
		m_head = m_head->next;
		return p;
	}

	/* release (0x140460 four / 0x1404b0 twelve; inlined into operator delete): only addresses inside
	 * the page go back on the free list. */
	bool release(T* page)
	{
		if (page < m_page || page >= m_tail)
			return false;

		m_count--;
		page->next = m_head;
		m_head = page;
		return true;
	}
private:
	T* m_page;
	T* m_head;
	T* m_tail;

	u32 m_bytes;
	u32 m_size;
	u32 m_count;
	u32 m_peak;
	u32 m_overflow;
};

